useEffect(() => {
    let cancelled = false;
    try {
        const params = new URLSearchParams(window.location.search);
        const assignmentId = _alloCleanQrAssignmentId(params.get('allo_assignment') || '');
        if (!assignmentId) return undefined;
        const firebaseHandoff = _alloReadQrFirebaseHandoff();
        const hostId = firebaseHandoff ? firebaseHandoff.appId : '';
        _alloSetQrStudentAiPolicy('pending', { type: 'assignment', assignmentId, hostAppId: hostId }, { clearCredentials: true });
        setHasSelectedMode(true);
        setHasSelectedRole(true);
        setShowWizard(false);
        setShowStudentWelcome(false);
        setIsTeacherMode(false);
        setIsParentMode(false);
        setIsIndependentMode(false);
        setIsStudentLinkMode(true);
        setShowStudentEntry(true);
        if (!firebaseHandoff) {
            addToast(ALLO_QR_INCOMPLETE_MESSAGE, 'error');
            return undefined;
        }
        setActiveSessionCode(null);
        setActiveSessionAppId(hostId);
        const loadAssignment = async () => {
            try {
                const assignmentUser = await _alloEnsureAuthenticatedUser();
                setUser(assignmentUser);
                const assignmentRef = doc(db, 'artifacts', hostId, 'public', 'data', 'sessions', assignmentId);
                const snap = await getDoc(assignmentRef);
                if (!snap.exists()) throw new Error('Assignment not found');
                const packet = snap.data() || {};
                _alloApplyAuthoritativeStudentAiPolicy(packet, { type: 'assignment', assignmentId, hostAppId: hostId, workStory: packet && packet.workStory === true });
                if (_alloAssignmentIsExpired(packet)) throw new Error('Assignment expired');
                const rawResources = Array.isArray(packet.resources) ? packet.resources : [];
                if (!rawResources.length) throw new Error('Assignment has no resources');
                const restoredResources = await hydrateSessionAssets(hostId, rawResources);
                if (!Array.isArray(restoredResources) || restoredResources.some(item => !item || item.__alloResourceRef || item.__alloResourcesManifestRef)) {
                    throw new Error('Assignment resource assets are unavailable');
                }
                if (cancelled) return;
                setHistory(restoredResources);
                setReceivedDeliveryResources(restoredResources);
                const firstId = packet.currentResourceId || restoredResources[0]?.id;
                // Directions v2 delivery rule: the assignment brief is the front page at every
                // student consumption point — a DELIVERY rule, not a storage reorder, so the
                // teacher's history/hand-ordering stays untouched. (Shelf open does the same.)
                const _dirFirst = restoredResources.find(item => item && item.type === 'directions');
                const firstResource = _dirFirst || restoredResources.find(item => item && item.id === firstId) || restoredResources[0];
                if (!firstResource) throw new Error('Assignment has no openable resource');
                setPendingQrAssignmentResource(firstResource);
                addToast('Homework loaded: ' + (packet.title || firstResource.title || 'AlloFlow assignment'), 'success');
            } catch (e) {
                warnLog('Homework QR load failed:', e);
                if (!cancelled) {
                    const message = String(e?.message || '').toLowerCase();
                    const code = String(e?.code || '').toLowerCase();
                    const recovery = message.includes('expired')
                        ? 'This homework link has expired. Ask your teacher for a new QR code.'
                        : message.includes('not found')
                            ? 'This homework link was revoked or is no longer available. Ask your teacher for a new QR code.'
                            : message.includes('no resources') || message.includes('no openable')
                                ? 'This homework link is incomplete. Ask your teacher to create it again.'
                                : code.includes('permission-denied')
                                    ? 'This homework link cannot access the teacher class storage. Ask your teacher to use a Class Mailbox or self-contained QR.'
                                    : 'Could not load this homework assignment. Check the connection, then retry or ask your teacher for a new QR code.';
                    addToast(recovery, 'error');
                }
            }
        };
        loadAssignment();
    } catch (e) {
        warnLog('Homework QR load failed:', e);
    }
    return () => { cancelled = true; };
}, []);

